## Code Example

```javascript
const Ajv = require("ajv");
const ajv = new Ajv();
const schema = {
  type: "object",
  properties: {
    id: { type: "string" },
    event: { type: "string" },
    customer_segment: { type: "string" }
  },
  required: ["id", "event"],
  additionalProperties: true
};
